_cache: dict[tuple[str, str, int], QIcon] = {}


def icon(name: str, color: str | QColor = "#444444", size: int = 24) -> QIcon:
    hex_color = QColor(color).name()
    key = (name, hex_color, size)
    if key not in _cache:
        svg = (f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24">'
               f'<path fill="{hex_color}" d="{PATHS[name]}"/></svg>').encode()
        renderer = QSvgRenderer(QByteArray(svg))
        scale = 2  # crisp on high-DPI screens
        pixmap = QPixmap(size * scale, size * scale)
        pixmap.fill(Qt.GlobalColor.transparent)
        painter = QPainter(pixmap)
        renderer.render(painter, QRectF(0, 0, size * scale, size * scale))
        painter.end()
        pixmap.setDevicePixelRatio(scale)
        _cache[key] = QIcon(pixmap)
    return _cache[key]
